import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;
import redis.clients.jedis.Jedis;

public class ElastiCacheRedisClient {
    private static final JedisPool pool;

    static {
        JedisPoolConfig poolConfig = new JedisPoolConfig();
        poolConfig.setMaxTotal(128);
        poolConfig.setMaxIdle(32);
        poolConfig.setMinIdle(8);
        poolConfig.setTestOnBorrow(true);

        // Configuration pointing to the ElastiCache Redis Configuration or Primary Endpoint
        pool = new JedisPool(poolConfig, "my-redis-cluster.pv7g9g.clustercfg.use1.cache.amazonaws.com", 6379, 2000);
    }

    public String getCachedUserSession(String sessionId) {
        try (Jedis jedis = pool.getResource()) {
            return jedis.get("session:" + sessionId);
        }
    }

    public void cacheUserSession(String sessionId, String sessionData, int ttlSeconds) {
        try (Jedis jedis = pool.getResource()) {
            jedis.setex("session:" + sessionId, ttlSeconds, sessionData);
        }
    }
}
